 if(index===5){text('SUNDAY',30,100,100,'serif');text('MARKET',30,205,100,'serif');circle(300,510,170,accent);for(let j=0;j<7;j++){g.strokeStyle=ink;g.lineWidth=6;g.beginPath();g.ellipse(300,510,30+j*20,165,0,0,Math.PI*2);g.stroke()}text('FRESH IDEAS / EVERY WEEK',45,720,23);text('09:00 — 16:00    •    COME AS YOU ARE',45,765,16)}
