 if(index===7){for(let j=0;j<12;j++){g.strokeStyle=ink;g.lineWidth=3;g.beginPath();g.arc(300,400,30+j*24,0,Math.PI*2);g.stroke()}rect(32,310,536,175,bg);text('BLUE',40,312,116);text('INTERVAL',42,425,65);text('A STUDY IN FREQUENCY',30,758,21)}
 if(index===8){text('GOOD',25,95,145);text('COMPANY',30,245,88);circle(200,535,112,ink);circle(400,535,112,accent);circle(175,510,10,bg);circle(225,510,10,bg);circle(375,510,10,bg);circle(425,510,10,bg);g.strokeStyle=bg;g.lineWidth=7;[200,400].forEach(x=>{g.beginPath();g.arc(x,545,38,0,Math.PI);g.stroke()});text('BETTER TOGETHER.',40,735,39)}
